package com.masalewala.api.security;
import com.masalewala.api.repository.Repositories.Users;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.context.annotation.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Configuration public class SecurityConfig{@Bean SecurityFilterChain filter(HttpSecurity http,JwtService jwt,Users users)throws Exception{return http.csrf(c->c.disable()).cors(c->{ }).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/admin/**").hasAuthority("ADMIN").requestMatchers("/api/auth/**","/api/products/**","/api/categories/**","/api/content/**","/api/orders/track/**").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt,users),UsernamePasswordAuthenticationFilter.class).build();}
static class JwtFilter extends OncePerRequestFilter{private final JwtService jwt;private final Users users;JwtFilter(JwtService jwt,Users users){this.jwt=jwt;this.users=users;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){var email=jwt.subject(h.substring(7));users.findByEmail(email).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(email,null,u.roles.stream().map(r->new SimpleGrantedAuthority(r.name())).toList())));}chain.doFilter(req,res);}}}
